package com.mvpief;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PluginLauncher
{
	public static void main(String[] args) throws Exception
	{
        //noinspection unchecked
        ExternalPluginManager.loadBuiltin(DailyAgility.class);
		RuneLite.main(args);
	}
}

package com.mvpief.export;

import com.mvpief.LogEntry;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Singleton;
import java.io.BufferedWriter;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;

/**
 * Writes {@link LogEntry} rows to a CSV file (RFC 4180-ish: comma-separated, quoted only when needed).
 * <p>
 * The writer is streamed and buffered, so the whole log is never assembled into one big String in
 * memory — exporting thousands of rows stays cheap. Call {@link #export} off the EDT.
 */
@Slf4j
@Singleton
public class CsvExporter
{
    private static final String HEADER = "date,course,laps,marks";

    /**
     * Writes every entry to {@code file}, overwriting any existing file at that path.
     *
     * @throws IOException if the file cannot be written
     */
    public void export(File file, List<LogEntry> entries) throws IOException
    {
        try (BufferedWriter writer = Files.newBufferedWriter(file.toPath(), StandardCharsets.UTF_8))
        {
            writer.write(HEADER);
            writer.newLine();

            for (LogEntry entry : entries)
            {
                writer.write(escape(entry.getDate()));
                writer.write(',');
                writer.write(escape(entry.getCourse()));
                writer.write(',');
                writer.write(Integer.toString(entry.getLaps()));
                writer.write(',');
                writer.write(Integer.toString(entry.getMarks()));
                writer.newLine();
            }
        }
    }

    /**
     * Quotes a field only when it contains a comma, quote, or line break, doubling any inner quotes.
     */
    private static String escape(String field)
    {
        if (field == null)
        {
            return "";
        }

        if (field.indexOf(',') >= 0 || field.indexOf('"') >= 0
                || field.indexOf('\n') >= 0 || field.indexOf('\r') >= 0)
        {
            return '"' + field.replace("\"", "\"\"") + '"';
        }

        return field;
    }
}

package com.mvpief;

import com.mvpief.state.SessionState;
import com.mvpief.export.CsvExporter;

import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.api.events.MenuOptionClicked;

import javax.inject.Inject;
import javax.swing.JFileChooser;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.time.LocalDate;

@Slf4j
@PluginDescriptor(name = "Daily Agility")
public class DailyAgility extends Plugin
{
	// region Constants

	private static final Pattern LAP_PATTERN = Pattern.compile("Your (.+) lap count is: (\\d+)");
	private static final int MARK_OF_GRACE_ID = 11849;

	// endregion

	// region Injected

	@Inject private ConfigManager configManager;
	@Inject private Client client;
	@Inject private DailyAgilityConfig config;
	@Inject private OverlayManager overlayManager;
	@Inject private DailyGoalOverlay overlay;
	@Inject private ClientThread clientThread;
	@Inject private LapTimer lapTimer;
	@Inject private SessionState sessionState;
	@Inject private ClientToolbar clientToolbar;
	@Inject private DailyAgilityPanel panel;
	@Inject private LogStore logStore;
	@Inject private CsvExporter csvExporter;

	// endregion

	// region State

	@Getter private String currentCourse = null;
	@Getter private int lastMarkCount = 0;
	private int lastBankMarkCount = -1; // -1 = bank not yet seen this session
	private boolean inventoryInitialized = false;
	private boolean droppedMarkPending = false;
	private int pendingMarkPickup = 0;
	private int pendingBankWithdrawal = 0;

	// endregion

	// region Lifecycle

	@Override
	protected void startUp() throws Exception
	{
		resetDailyProgressIfNewDay();
		restoreLastKnownCourse();
		initInventory();
		initPanel();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		inventoryInitialized = false;
		lapTimer.reset();
		overlayManager.remove(overlay);
	}

	// endregion

	// region Getters

	public long getLastLapDuration()
	{
		return lapTimer.getLastLapDuration();
	}

	public double getAverageLapTime(String course)
	{
		return lapTimer.getAverageLapTime(course);
	}

	public int getLapsLeft()
	{
		return config.lapsRemaining();
	}

	public int getMarksLeft()
	{
		return config.marksRemaining();
	}


	public long getEstimatedTimeRemainingMs()
	{
		if (currentCourse == null) return -1;
		double avg = getAverageLapTime(currentCourse);
		if (avg < 0) return -1;
		int laps = config.lapsRemaining();
		if (laps <= 0) return 0;
		return (long) (avg * laps);
	}

	// endregion

	// region Internals

	private void resetDailyProgressIfNewDay()
	{
		String today = LocalDate.now().toString();
		String lastDate = config.lastSavedDate();

		if (!today.equals(lastDate))
		{
			configManager.setConfiguration(DailyAgilityConfig.GROUP, "lapsRemaining", config.dailyGoal());
			configManager.setConfiguration(DailyAgilityConfig.GROUP, "marksRemaining", config.marksGoal());
			configManager.setConfiguration(DailyAgilityConfig.GROUP, "lastSavedDate", today);
		}
	}

	private void initInventory()
	{
		clientThread.invokeLater(() ->
		{
			ItemContainer inventory = client.getItemContainer(InventoryID.INV);
			if (inventory == null)
			{
				return false; // retry next tick
			}

			lastMarkCount = Arrays.stream(inventory.getItems())
					.filter(item -> item.getId() == MARK_OF_GRACE_ID)
					.mapToInt(Item::getQuantity)
					.sum();
			inventoryInitialized = true;
			return true; // done
		});
	}

	private void initPanel()
	{
		final BufferedImage rawIcon = ImageUtil.loadImageResource(getClass(), "panel_logo.png");
		final BufferedImage icon = ImageUtil.resizeImage(rawIcon, 16, 16);

        // lower = further left in the sidebar
        NavigationButton navButton = NavigationButton.builder()
                .tooltip("Daily Agility")
                .icon(icon)
                .priority(6)           // lower = further left in the sidebar
                .panel(panel)
                .build();

		clientToolbar.addNavigation(navButton);
		panel.setOnDateSelected(date -> panel.setLogEntries(logStore.getEntries(null, date)));
		panel.setOnExport(this::exportLog);

		refreshPanel();
		refreshCalendarHighlights();
	}

	private void exportLog()
	{
		// Runs on the Swing EDT (button click); the file chooser must stay here.
		JFileChooser chooser = new JFileChooser();
		chooser.setDialogTitle("Export Daily Agility Log");
		chooser.setSelectedFile(new File("daily-agility-" + LocalDate.now() + ".csv"));
		chooser.setFileFilter(new FileNameExtensionFilter("CSV files (*.csv)", "csv"));

		if (chooser.showSaveDialog(panel) != JFileChooser.APPROVE_OPTION) return;

		File chosen = chooser.getSelectedFile();
		final File target = chosen.getName().toLowerCase().endsWith(".csv")
				? chosen
				: new File(chosen.getParentFile(), chosen.getName() + ".csv");

		// Gather rows + write off the EDT so a large log never freezes the client.
		new Thread(() ->
		{
			try
			{
				List<LogEntry> entries = logStore.getEntries(null);
				csvExporter.export(target, entries);
				log.info("Exported {} Daily Agility log entries to {}", entries.size(), target);
			}
			catch (IOException e)
			{
				log.error("Failed to export Daily Agility log to {}", target, e);
			}
		}, "DailyAgility-CSV-Export").start();
	}

	private void refreshPanel()
	{
		LocalDate selected = panel.getSelectedDate();

		// Laps/marks always log to today, so a new lap only changes views that include today.
		// Re-query when showing all dates (null) or today's filter; leave a past-date view
		// untouched so the selected filter doesn't snap back to "all dates".
		if (selected == null)
		{
			panel.setLogEntries(logStore.getEntries(null));
		}
		else if (selected.equals(LocalDate.now()))
		{
			panel.setLogEntries(logStore.getEntries(null, selected));
		}
	}

	private void refreshCalendarHighlights()
	{
		Set<LocalDate> dates = logStore.getKnownDates().stream()
				.map(LocalDate::parse)
				.collect(java.util.stream.Collectors.toSet());
		panel.setDatesWithData(dates);
	}

	private void subtractLaps(int count)
	{
		int newLapCount = config.lapsRemaining() - count;
		configManager.setConfiguration(DailyAgilityConfig.GROUP, "lapsRemaining", newLapCount);
		refreshPanel();
		refreshCalendarHighlights();
	}

	private void markPickUp(int count)
	{
		int newCount = config.marksRemaining() - count;
		configManager.setConfiguration(DailyAgilityConfig.GROUP, "marksRemaining", newCount);
		if (currentCourse != null) logStore.recordMarks(currentCourse, count);
		refreshPanel();
	}

	private void restoreLastKnownCourse()
	{
		String saved = config.lastKnownCourse();
		if (saved != null && !saved.isEmpty())
		{
			currentCourse = saved;
			sessionState.setCurrentCourse(saved);
		}
	}

	// endregion

	// region Events

	@Subscribe
	public void onMenuOptionClicked(net.runelite.api.events.MenuOptionClicked event)
	{
		if (event.getItemId() == MARK_OF_GRACE_ID
				&& event.getMenuOption().equalsIgnoreCase("Drop"))
		{
			droppedMarkPending = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// startUp() only fires when the plugin loads, not on login — so re-check the day
		// whenever the player logs in, to handle the client being left running overnight.
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			resetDailyProgressIfNewDay();
			// Re-baseline on every login/world-hop so marks already in the
			// inventory are never counted as newly collected.
			inventoryInitialized = false;
			lastBankMarkCount = -1;
			droppedMarkPending = false;
			pendingMarkPickup = 0;
			pendingBankWithdrawal = 0;
			initInventory();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		if (chatMessage.getType() != ChatMessageType.GAMEMESSAGE) return;

		String clean = chatMessage.getMessage().replaceAll("<[^>]+>", "");
		Matcher matcher = LAP_PATTERN.matcher(clean);
		if (matcher.find())
		{
			// Also covers staying logged in across midnight.
			resetDailyProgressIfNewDay();

			// Strip a trailing "Rooftop" so course names/log keys stay consistent
			// with history recorded before Rooftop-only messages were supported.
			String course = matcher.group(1).replaceAll("\\s+Rooftop$", "");
			currentCourse = course;
			configManager.setConfiguration(DailyAgilityConfig.GROUP, "lastKnownCourse", course);

			// The chat message reports the account's authoritative total lap count for
			// the course, not "+1" — diff it against the last known total so gaps (e.g.
			// laps done across days this was missed) get attributed to the right day(s)
			// instead of dumping them all on today.
			int newTotal = Integer.parseInt(matcher.group(2));
			int lapsToday = logStore.recordLapTotal(course, newTotal);
			if (lapsToday > 0) subtractLaps(lapsToday);

			lapTimer.recordLap(course);
			sessionState.setCurrentCourse(course);
			sessionState.markActivity();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(DailyAgilityConfig.GROUP)) return;

		// TODO: make a button to set the current lapsRemaining to the current goal & make it increase by delta.
		// For now the lap counter just resets to the new dailGoal when changed.
		if (event.getKey().equals("dailyGoal"))
		{
			configManager.setConfiguration(DailyAgilityConfig.GROUP, "lapsRemaining", config.dailyGoal());
		}
		if (event.getKey().equals("marksGoal"))
		{
			configManager.setConfiguration(DailyAgilityConfig.GROUP, "marksRemaining", config.marksGoal());
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Inventory and bank container events both fire within the same tick.
		// Subtract any bank withdrawal from the inventory gain so that only
		// marks actually picked up from the ground are counted.
		int net = pendingMarkPickup - pendingBankWithdrawal;
		if (net > 0)
		{
			markPickUp(net);
		}
		pendingMarkPickup = 0;
		pendingBankWithdrawal = 0;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();

		if (containerId == InventoryID.BANK)
		{
			int currentBankCount = countMarks(event.getItemContainer());
			if (lastBankMarkCount >= 0 && currentBankCount < lastBankMarkCount)
			{
				pendingBankWithdrawal += lastBankMarkCount - currentBankCount;
			}
			lastBankMarkCount = currentBankCount;
			return;
		}

		if (containerId != InventoryID.INV) return;

		int currentCount = countMarks(event.getItemContainer());

		if (!inventoryInitialized)
		{
			lastMarkCount = currentCount;
			inventoryInitialized = true;
			return;
		}

		if (droppedMarkPending && currentCount < lastMarkCount)
		{
			// The intentional drop landed — freeze lastMarkCount at the pre-drop value
			// so picking the same mark back up shows a zero net delta.
			droppedMarkPending = false;
			return;
		}
		droppedMarkPending = false;

		if (currentCount > lastMarkCount)
		{
			pendingMarkPickup += currentCount - lastMarkCount;
		}

		lastMarkCount = currentCount;
	}

	private int countMarks(ItemContainer container)
	{
		return Arrays.stream(container.getItems())
				.filter(item -> item.getId() == MARK_OF_GRACE_ID)
				.mapToInt(Item::getQuantity)
				.sum();
	}

	// endregion

	// region Config

	@Provides
	DailyAgilityConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DailyAgilityConfig.class);
	}

	// endregion
}

package com.mvpief;

import net.runelite.client.config.ConfigManager;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

@Slf4j
@Singleton
public class LogStore
{
    private static final String KEY_KNOWN_COURSES = "knownCourses";
    private static final String KEY_KNOWN_DATES = "knownDates";
    private static final String KEY_LAST_LAP_COUNT_PREFIX = "lastLapCount_";
    private static final String KEY_LAST_LAP_DATE_PREFIX = "lastLapCountDate_";

    @Inject private ConfigManager configManager;
    @Inject private DailyAgilityConfig config;

    // region Public API

    /**
     * Feeds the course's authoritative total lap count (as reported verbatim by the game's
     * chat message) and reconciles it against the last known total for that course.
     * The game — not this code — is the source of truth for how many laps happened;
     * this only figures out which day(s) to attribute them to.
     * <p>
     * If the total advanced by more than 1 since the last message and the last message was
     * on an earlier day, the gap is spread evenly (whole laps only) across the days between,
     * with the remainder attributed to today. Returns the number of laps attributed to today,
     * which is what should count against today's remaining goal.
     */
    public int recordLapTotal(String course, int newTotal)
    {
        String today = LocalDate.now().toString();
        Integer lastCount = getLastLapCount(course);
        String lastDate = getLastLapCountDate(course);

        int lapsToday;
        if (lastCount == null || lastDate == null)
        {
            // No baseline yet for this course — we can't know how many laps happened
            // before now, so just count this one for today rather than guessing.
            lapsToday = 1;
            if (config.logEntries()) addLaps(course, today, 1);
        }
        else
        {
            int diff = newTotal - lastCount;
            if (diff <= 0)
            {
                // Duplicate message, or the counter went backwards — nothing new to log.
                lapsToday = 0;
            }
            else if (lastDate.equals(today))
            {
                lapsToday = diff;
                if (config.logEntries()) addLaps(course, today, diff);
            }
            else
            {
                lapsToday = distributeLaps(course, lastDate, today, diff, config.logEntries());
            }
        }

        saveLastLapCount(course, newTotal, today);
        return lapsToday;
    }

    /**
     * Increments the mark count for the given course on today's date.
     */
    public void recordMarks(String course, int count)
    {
        if (!config.logEntries()) return;
        String date = LocalDate.now().toString();
        LogEntry current = getEntry(date, course);
        saveEntry(date, course, current.getLaps(), current.getMarks() + count);
    }

    public List<LogEntry> getEntries(String courseFilter)
    {
        return getEntries(courseFilter, null);
    }

    public List<LogEntry> getEntries(String courseFilter, LocalDate dateFilter)
    {
        List<String> courses = courseFilter != null
                ? Collections.singletonList(courseFilter)
                : getKnownCourses();

        List<String> dates = dateFilter != null
                ? Collections.singletonList(dateFilter.toString())
                : getKnownDates();

        List<LogEntry> entries = new ArrayList<>();

        for (String dateStr : dates)
        {
            for (String course : courses)
            {
                String key = buildKey(dateStr, course);
                String stored = configManager.getConfiguration(DailyAgilityConfig.GROUP, key);
                if (stored != null && !stored.isEmpty())
                {
                    entries.add(parse(dateStr, course, stored));
                }
            }
        }

        return entries;
    }

    public List<String> getKnownDates()
    {
        String stored = configManager.getConfiguration(DailyAgilityConfig.GROUP, KEY_KNOWN_DATES);
        if (stored == null || stored.isEmpty()) return new ArrayList<>();
        return Arrays.stream(stored.split(","))
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                // ISO date strings sort lexicographically, newest first
                .sorted(Collections.reverseOrder())
                .collect(Collectors.toList());
    }

    /**
     * Returns the list of every course that has ever been logged.
     */
    public List<String> getKnownCourses()
    {
        String stored = configManager.getConfiguration(DailyAgilityConfig.GROUP, KEY_KNOWN_COURSES);
        if (stored == null || stored.isEmpty()) return new ArrayList<>();
        return Arrays.stream(stored.split(","))
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                .collect(Collectors.toList());
    }

    // endregion

    // region Internals

    /**
     * Spreads {@code diff} laps evenly (whole numbers) across every day strictly after
     * {@code lastDateStr} up to and including {@code todayStr}, with any remainder from
     * the division added to today. Returns the count attributed to today either way,
     * regardless of {@code persist}, since that figure is still needed to decrement
     * today's remaining goal even when log-entry persistence is disabled.
     */
    private int distributeLaps(String course, String lastDateStr, String todayStr, int diff, boolean persist)
    {
        LocalDate lastDate = LocalDate.parse(lastDateStr);
        LocalDate today = LocalDate.parse(todayStr);
        long numDays = ChronoUnit.DAYS.between(lastDate, today);

        if (numDays <= 0)
        {
            if (persist) addLaps(course, todayStr, diff);
            return diff;
        }

        int share = (int) (diff / numDays);
        int remainder = (int) (diff % numDays);

        if (persist)
        {
            LocalDate date = lastDate.plusDays(1);
            for (long i = 0; i < numDays - 1; i++)
            {
                addLaps(course, date.toString(), share);
                date = date.plusDays(1);
            }
        }

        int todayLaps = share + remainder;
        if (persist) addLaps(course, todayStr, todayLaps);
        return todayLaps;
    }

    private void addLaps(String course, String date, int count)
    {
        if (count <= 0) return;
        LogEntry current = getEntry(date, course);
        saveEntry(date, course, current.getLaps() + count, current.getMarks());
        registerCourse(course);
        registerDate(date);
    }

    private Integer getLastLapCount(String course)
    {
        String stored = configManager.getConfiguration(DailyAgilityConfig.GROUP, KEY_LAST_LAP_COUNT_PREFIX + normalizeCourse(course));
        if (stored == null || stored.isEmpty()) return null;
        try
        {
            return Integer.parseInt(stored);
        }
        catch (NumberFormatException e)
        {
            log.error("Failed to parse last lap count for {}: {}", course, stored);
            return null;
        }
    }

    private String getLastLapCountDate(String course)
    {
        String stored = configManager.getConfiguration(DailyAgilityConfig.GROUP, KEY_LAST_LAP_DATE_PREFIX + normalizeCourse(course));
        return (stored == null || stored.isEmpty()) ? null : stored;
    }

    private void saveLastLapCount(String course, int count, String date)
    {
        configManager.setConfiguration(DailyAgilityConfig.GROUP, KEY_LAST_LAP_COUNT_PREFIX + normalizeCourse(course), String.valueOf(count));
        configManager.setConfiguration(DailyAgilityConfig.GROUP, KEY_LAST_LAP_DATE_PREFIX + normalizeCourse(course), date);
    }

    private String normalizeCourse(String course)
    {
        return course.toLowerCase().replace(" ", "_");
    }

    private LogEntry getEntry(String date, String course)
    {
        String key = buildKey(date, course);
        String stored = configManager.getConfiguration(DailyAgilityConfig.GROUP, key);
        if (stored == null || stored.isEmpty()) return new LogEntry(date, course, 0, 0);
        return parse(date, course, stored);
    }

    private void saveEntry(String date, String course, int laps, int marks)
    {
        String key = buildKey(date, course);
        configManager.setConfiguration(DailyAgilityConfig.GROUP, key, laps + "," + marks);
    }

    private void registerCourse(String course)
    {
        List<String> courses = getKnownCourses();
        if (courses.contains(course)) return;
        courses.add(course);
        configManager.setConfiguration(
                DailyAgilityConfig.GROUP,
                KEY_KNOWN_COURSES,
                String.join(",", courses)
        );
    }

    private void registerDate(String date)
    {
        List<String> dates = getKnownDates();
        if (dates.contains(date)) return;
        dates.add(date);
        configManager.setConfiguration(
                DailyAgilityConfig.GROUP,
                KEY_KNOWN_DATES,
                String.join(",", dates)
        );
    }

    private LogEntry parse(String date, String course, String stored)
    {
        try
        {
            String[] parts = stored.split(",");
            int laps = Integer.parseInt(parts[0]);
            int marks = parts.length > 1 ? Integer.parseInt(parts[1]) : 0;
            return new LogEntry(date, course, laps, marks);
        }
        catch (Exception e)
        {
            log.error("Failed to parse log entry for {} on {}: {}", course, date, stored);
            return new LogEntry(date, course, 0, 0);
        }
    }

    private String buildKey(String date, String course)
    {
        // e.g. "log_2026-05-05_seers_village"
        return "log_" + date + "_" + normalizeCourse(course);
    }

    // endregion
}

package com.mvpief;

import lombok.Value;

@Value
public class LogEntry
{
    String date;
    String course;
    int laps;
    int marks;
}

package com.mvpief;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(DailyAgilityConfig.GROUP)
public interface DailyAgilityConfig extends Config
{
	String GROUP = "dailyAgility";

	@ConfigSection(name = "Laps", description = "Lap goal and display settings", position = 0)
	String lapsSection = "laps";

	@ConfigSection(name = "Marks of Grace", description = "Marks of Grace goal settings", position = 1)
	String marksSection = "marks";

	@ConfigSection(name = "Display", description = "Overlay display options", position = 2)
	String displaySection = "display";

	@ConfigSection(name = "Logging", description = "Logging options", position = 3)
	String loggingSection = "logging";

	// --- Laps ---
	@ConfigItem(keyName = "dailyGoal", name = "Daily Lap Goal", description = "How many rooftop laps to complete today.", position = 0, section = lapsSection)
	default int dailyGoal() { return 100; }

	@ConfigItem(keyName = "lapsRemaining", name = "", description = "", hidden = true, section = lapsSection)
	default int lapsRemaining() { return -1; }

	// --- Marks ---
	@ConfigItem(keyName = "marksGoal", name = "Daily Marks Goal", description = "Marks of Grace to collect today.", position = 0, section = marksSection)
	default int marksGoal() { return 10; }

	@ConfigItem(keyName = "marksRemaining", name = "", description = "", hidden = true, section = marksSection)
	default int marksRemaining() { return 0; }

	// --- Display ---
	@ConfigItem(
			keyName = "overlayDisplayMode",
			name = "Overlay Mode",
			description = "Controls which overlay panels are rendered.",
			position = 0,
			section = displaySection
	)
	default OverlayDisplayMode overlayDisplayMode() { return OverlayDisplayMode.ALWAYS; }

	@ConfigItem(keyName = "showLapsLeft", name = "Show Laps Left", description = "Show the laps left on the overlay.", position = 0, section = displaySection)
	default boolean showLapsLeft() { return true; }

	@ConfigItem(keyName = "showMarksLeft", name = "Show Marks Left", description = "Show the marks left on the overlay.", position = 1, section = displaySection)
	default boolean showMarksLeft() { return true; }

	@ConfigItem(keyName = "showLapTime", name = "Show Last Lap Time", description = "Show the last lap time on the overlay.", position = 2, section = displaySection)
	default boolean showLapTime() { return true; }

	@ConfigItem(keyName = "showAverageTime", name = "Show Average Time", description = "Show average lap time on the overlay.", position = 3, section = displaySection)
	default boolean showAverageTime() { return true; }

	@ConfigItem(keyName = "showETA", name = "Show ETA", description = "Show estimated time remaining on the overlay.", position = 4, section = displaySection)
	default boolean showETA() { return true; }

	@ConfigItem(keyName = "logEntries", name = "Log daily laps", description = "Logs the daily laps and mark of grace.", position = 0, section = loggingSection)
	default boolean logEntries() { return true; }

	// --- Internal ---
	@ConfigItem(keyName = "lastSavedDate", name = "", description = "", hidden = true)
	default String lastSavedDate() { return ""; }

	@ConfigItem(keyName = "lastKnownCourse", name = "", description = "", hidden = true)
	default String lastKnownCourse() { return ""; }
}

package com.mvpief.state;

import com.mvpief.DailyAgilityConfig;
import lombok.Getter;
import lombok.Setter;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class SessionState {
    // Consider the player "running" only if a lap was completed within this window.
    private static final long RUNNING_TIMEOUT_MS = 10 * 60 * 1000; // 10 minutes

    @Inject private DailyAgilityConfig config;

    @Getter @Setter private String currentCourse = null;
    @Getter @Setter private int lastMarkCount = 0;
    @Getter @Setter private boolean inventoryInitialized = false;

    // Timestamp (ms) of the last lap completion; 0 means no activity this session.
    private long lastActivityMs = 0;

    public boolean isGoalAchieved()
    {
        return config.lapsRemaining() + config.marksRemaining() <= 0;
    }

    /** Marks the player as actively running right now. Call on each completed lap. */
    public void markActivity()
    {
        lastActivityMs = System.currentTimeMillis();
    }

    public boolean isRunning()
    {
        return currentCourse != null
                && lastActivityMs != 0
                && (System.currentTimeMillis() - lastActivityMs) < RUNNING_TIMEOUT_MS;
    }

    public void reset()
    {
        currentCourse = null;
        lastMarkCount = 0;
        inventoryInitialized = false;
        lastActivityMs = 0;
    }
}

package com.mvpief;

import net.runelite.client.config.ConfigManager;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import lombok.Getter;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class LapTimer
{
    private static final int MAX_LAP_HISTORY = 100;

    private static final long MAX_LAP_DURATION_MS = 5 * 60 * 1000; // 10 minutes

    private final ConfigManager configManager;

    private long lastLapTime = -1;
    @Getter private long lastLapDuration = -1;

    @Inject
    public LapTimer(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    public void recordLap(String course)
    {
        long now = System.currentTimeMillis();
        if (lastLapTime != -1)
        {
            long duration = now - lastLapTime;
            if (duration <= MAX_LAP_DURATION_MS)
            {
                lastLapDuration = duration;
                saveLapTime(course, lastLapDuration);
            }
            // else: gap too large (AFK/logged out) — skip timing, just re-baseline below.
        }
        lastLapTime = now;
    }

    public double getAverageLapTime(String course)
    {
        List<Long> history = getLapHistory(course);
        if (history.isEmpty()) return -1;
        return history.stream().mapToLong(Long::longValue).average().orElse(-1);
    }

    public void reset()
    {
        lastLapTime = -1;
        lastLapDuration = -1;
    }

    private List<Long> getLapHistory(String course)
    {
        String key = "lapHistory_" + course.replace(" ", "_");
        String stored = configManager.getConfiguration(DailyAgilityConfig.GROUP, key);
        if (stored == null || stored.isEmpty()) return new ArrayList<>();
        return Arrays.stream(stored.split(","))
                .map(Long::parseLong)
                .collect(Collectors.toList());
    }

    private void saveLapTime(String course, long duration)
    {
        List<Long> history = getLapHistory(course);
        history.add(duration);
        if (history.size() > MAX_LAP_HISTORY)
        {
            history = history.subList(history.size() - MAX_LAP_HISTORY, history.size());
        }
        String key = "lapHistory_" + course.replace(" ", "_");
        String value = history.stream().map(String::valueOf).collect(Collectors.joining(","));
        configManager.setConfiguration(DailyAgilityConfig.GROUP, key, value);
    }
}

package com.mvpief;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum OverlayDisplayMode
{
    ALWAYS("Always Show"),
    ON_GOAL("Show when goal is not completed"),
    ON_RUNNING("Only show when running rooftops"),
    NEVER("Never show the overlay");

    private final String name;

    @Override
    public String toString()
